// @deno-types="https://cdn.sheetjs.com/xlsx-0.20.3/package/types/index.d.ts"
import * as XLSX from "https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs";
// (or vendor xlsx.mjs + types into _shared/vendor/ - SheetJS recommends vendoring; 1.0 MB)

export type SheetLine = { ref: string; text: string };

export function readWorkbook(bytes: Uint8Array, kind: "xlsx" | "xls" | "csv"): XLSX.WorkBook {
  if (kind === "csv") {
    let text: string;
    try { text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); } // strips BOM
    catch { text = new TextDecoder("gb18030").decode(bytes); }            // Chinese Excel exports
    return XLSX.read(text, { type: "string" }); // NOT type:'array' -> mojibake without BOM
  }
  return XLSX.read(bytes, { type: "array", dense: true });
}

export function workbookLines(wb: XLSX.WorkBook, maxRows = 2000): SheetLine[] {
  const out: SheetLine[] = [];
  wb.SheetNames.forEach((name, i) => {
    if (wb.Workbook?.Sheets?.[i]?.Hidden) return; // skip hidden sheets
    const ws = wb.Sheets[name];
    if (!ws?.["!ref"]) return;
    const start = XLSX.utils.decode_range(ws["!ref"]).s.r;
    const rows = XLSX.utils.sheet_to_json<unknown[]>(ws, { header: 1, raw: false, defval: "", blankrows: true });
    rows.forEach((r, idx) => {
      const cells = r.map((c) => String(c ?? "").replace(/\s+/g, " ").trim());
      while (cells.length && !cells[cells.length - 1]) cells.pop();
      if (!cells.some(Boolean)) return;
      out.push({ ref: `${name}!R${start + idx + 1}`, text: cells.join(" | ") });
    });
  });
  if (out.length > maxRows) throw new Error(`too many rows (${out.length})`);
  return out;
}
// Chunk ~120-150 product lines per Claude call; repeat the sheet's first header-ish lines
// at the top of every chunk as context, e.g. `[context] Harga!R3: No | Item / 货品 | Saiz | Unit | Harga (RM) | MOQ`.

export const UNITS = ["carton", "pack", "bag", "roll", "bundle", "box", "piece", "dozen", "kg"] as const;
const nullableInt = (description: string) => ({ type: ["integer", "null"], description });

export const PRICE_LIST_SCHEMA = {
  type: "object",
  properties: {
    supplier_name: { type: ["string", "null"], description: "Wholesaler/company name printed on the list, else null." },
    order_min_sen: nullableInt("Order-level minimum in sen (e.g. 'min order RM300' -> 30000), else null."),
    document_notes: { type: ["string", "null"], description: "One or two sentences the reviewer must know about the whole document, else null." },
    rows: {
      type: "array",
      items: {
        type: "object",
        properties: {
          name: { type: "string" },
          unit: { type: "string", enum: [...UNITS] },
          unit_raw: { type: "string", description: "Unit text exactly as written (e.g. '箱', 'ctn', 'kati'); '' if none." },
          pack_qty: nullableInt("Individual pieces in one selling unit."),
          price_sen: nullableInt("Price for one selling unit in sen."),
          min_order_qty: nullableInt("Minimum order in selling units."),
          confidence: { type: "number", description: "0.0 to 1.0" },
          raw_text: { type: "string" },
          source_ref: { type: "string", description: "Spreadsheet row label (e.g. Harga!R12) or 'p1 line 12'." },
          notes: { type: ["string", "null"] },
        },
        required: ["name", "unit", "unit_raw", "pack_qty", "price_sen", "min_order_qty", "confidence", "raw_text", "source_ref", "notes"],
        additionalProperties: false,
      },
    },
    unreadable: {
      type: "array",
      items: {
        type: "object",
        properties: { raw_text: { type: "string" }, source_ref: { type: "string" }, reason: { type: "string" } },
        required: ["raw_text", "source_ref", "reason"],
        additionalProperties: false,
      },
    },
  },
  required: ["supplier_name", "order_min_sen", "document_notes", "rows", "unreadable"],
  additionalProperties: false,
};

import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";

const Row = z.object({
  name: z.string().trim().min(1),
  unit: z.string().transform((u) => u.toLowerCase()).pipe(z.enum(UNITS)), // enum casing not guaranteed
  unit_raw: z.string(),
  pack_qty: z.number().int().positive().nullable().catch(null),
  price_sen: z.number().int().nonnegative().nullable(),
  min_order_qty: z.number().int().positive().nullable().catch(null),
  confidence: z.number().transform((c) => Math.min(1, Math.max(0, c))), // API can't enforce min/max
  raw_text: z.string(), source_ref: z.string(), notes: z.string().nullable(),
});
const Result = z.object({
  supplier_name: z.string().nullable(), order_min_sen: z.number().int().nullable(),
  document_notes: z.string().nullable(), rows: z.array(Row),
  unreadable: z.array(z.object({ raw_text: z.string(), source_ref: z.string(), reason: z.string() })),
});

export type Source =
  | { kind: "image"; mediaType: "image/jpeg" | "image/png" | "image/webp"; base64: string }
  | { kind: "pdf"; base64: string }
  | { kind: "rows"; text: string };

const client = new Anthropic({ apiKey: Deno.env.get("ANTHROPIC_API_KEY"), maxRetries: 2, timeout: 300_000 /* ms */ });

export async function extract(systemPrompt: string, src: Source) {
  const tag = crypto.randomUUID().slice(0, 8);
  const content: Anthropic.Beta.BetaContentBlockParam[] = [];
  if (src.kind === "image") content.push({ type: "image", source: { type: "base64", media_type: src.mediaType, data: src.base64 } });
  if (src.kind === "pdf") content.push({ type: "document", source: { type: "base64", media_type: "application/pdf", data: src.base64 } });
  if (src.kind === "rows") content.push({ type: "text", text: `<pasted_content id="${tag}">\n${src.text}\n</pasted_content id="${tag}">` });
  content.push({ type: "text", text: "Extract every product row from the attached price list into the JSON format." });

  const msg = await client.beta.messages.stream({
    model: "claude-opus-5-5",
    max_tokens: 32000,                       // thinking + JSON; >21,333 requires streaming in the TS SDK
    betas: ["server-side-fallback-2026-07-01"],
    fallbacks: "default",                    // retries policy declines on Anthropic's recommended model
    output_config: { effort: "medium", format: { type: "json_schema", schema: PRICE_LIST_SCHEMA } },
    system: [{ type: "text", text: systemPrompt, cache_control: { type: "ephemeral" } }],
    messages: [{ role: "user", content }],
    // never: temperature/top_p/top_k (400 on 2026-10-21), thinking:{type:'disabled'} (400), tool_choice any/tool (400)
  }).finalMessage();

  if (msg.stop_reason === "refusal") return { ok: false as const, error: "refusal", detail: msg.stop_details };
  if (msg.stop_reason === "max_tokens") return { ok: false as const, error: "truncated" }; // split chunk & retry
  const lastFallback = msg.content.map((b) => b.type).lastIndexOf("fallback");
  const text = msg.content.slice(lastFallback + 1).flatMap((b) => (b.type === "text" ? [b.text] : [])).join("");
  let json: unknown;
  try { json = JSON.parse(text); } catch { return { ok: false as const, error: "invalid_json" }; }
  const parsed = Result.safeParse(json);
  if (!parsed.success) return { ok: false as const, error: "schema", detail: parsed.error.issues };
  return { ok: true as const, data: parsed.data, servedBy: msg.model, usage: msg.usage };
}

export function sniff(b: Uint8Array): "image/jpeg" | "image/png" | "image/webp" | "pdf" | "xlsx" | "xls" | "unknown" {
  const s = (i: number, n: number) => String.fromCharCode(...b.subarray(i, i + n));
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return "image/jpeg";
  if (b[0] === 0x89 && s(1, 3) === "PNG") return "image/png";
  if (s(0, 4) === "RIFF" && s(8, 4) === "WEBP") return "image/webp";
  if (s(0, 5) === "%PDF-") return "pdf";
  if (b[0] === 0x50 && b[1] === 0x4b && b[2] === 0x03 && b[3] === 0x04) return "xlsx"; // zip container
  if (b[0] === 0xd0 && b[1] === 0xcf && b[2] === 0x11 && b[3] === 0xe0) return "xls";  // OLE2
  return "unknown"; // HEIC etc. -> reject (Claude accepts only jpeg/png/gif/webp)
}
// base64: import { encodeBase64 } from "@std/encoding/base64"; (std 1.0.11; ~39 ms for 7 MB locally)
